{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C53"],
      "claim": "Meperidine, a direct N-methylpiperidine analogue, has an absolute oral bioavailability of 0.48 in healthy volunteers, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Ketobemidone, another N-methylpiperidine opioid, has a mean absolute oral bioavailability of 34% (range 17–62%), supporting F ≥ 20% despite interindividual variability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Fenspiride, a spiro-piperidine with a polar heterocycle, shows almost complete absolute oral bioavailability of 90%, supporting that this scaffold class can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Codeine, a related N-methylated opioid, has reported oral bioavailability of 40–70%, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Meptazinol, a basic N-methyl azepane phenol, has low absolute oral bioavailability of about 9% (range 2–19%), providing a contradictory example of extensive first-pass metabolism, though its structural transfer to the query is limited.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small, lipophilic N-methylpiperidine spiro-oxetane. Most transferable experimental analogues with N-methylpiperidine or spiro-piperidine scaffolds show oral bioavailability above 20% (meperidine ~48–63%, ketobemidone ~34%, codeine ~40–70%, fenspiride ~90%). The main contradictory analogue, meptazinol, has low F but is structurally more distant and its low bioavailability reflects extensive first-pass metabolism; it does not outweigh the consistent high-F evidence. Therefore, F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "Morgan similarities to evidence molecules are low to moderate (0.18–0.24), limiting structural transferability.",
    "No analogue with the exact oxetane-spiro-piperidine combination was available.",
    "Opioid bioavailability values are variable, and meptazinol demonstrates that basic amine-containing analgesics can have low F due to first-pass metabolism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

